## C++ Implementation

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;          // read sizes

    vector<int> a(n), b(m);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int j = 0; j < m; ++j) cin >> b[j];

    // 1. Sort both arrays in place
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    // 2. Two‑pointer scan
    int i = 0, j = 0;
    bool found = false;
    while (i < n && j < m) {
        if (a[i] == b[j]) {
            cout << a[i] << '\n';
            found = true;
            ++i; ++j;
        } else if (a[i] < b[j]) {
            ++i;
        } else {
            ++j;
        }
    }

    if (!found) cout << "No common elements\n";
    return 0;
}
```

### How to run

```bash
g++ -std=c++17 -O2 -pipe -static -s -o common common.cpp
./common
```

**Input format**

```
n m
a1 a2 ... an
b1 b2 ... bm
```

**Example**

```
Input:
5 6
1 5 3 9 7
4 1 7 2 9 8

Output:
1
7
9
```

